"use client";

import { useEffect, useState } from "react";
import { CalendarCheck, Loader2, MapPin, UserRound } from "lucide-react";
import { api, ApiError } from "@/lib/api-client";

type Order={id:string;serviceTitle:string;serviceSlug:string;customerEmail:string;customerFirstName:string|null;customerLastName:string|null;amount:number|string;status:string;payment_status:string;booking_date:string|null;booking_time:string|null;location:string|null;notes:string|null;created_at:string};
const nextActions:Record<string,string[]>={PENDING:["CANCELLED"],CONFIRMED:["IN_PROGRESS","CANCELLED"],IN_PROGRESS:["COMPLETED","CANCELLED"],COMPLETED:[],CANCELLED:[]};
const label=(v:string)=>v.replaceAll("_"," ").toLowerCase().replace(/\b\w/g,c=>c.toUpperCase());
export default function ServiceOrdersPage(){const[orders,setOrders]=useState<Order[]>([]);const[loading,setLoading]=useState(true);const[busy,setBusy]=useState("");const[error,setError]=useState("");
 async function load(){setLoading(true);try{const r=await api.get<{serviceOrders:Order[]}>("/api/service-orders/vendor/mine");setOrders(r.serviceOrders)}catch(e){setError(e instanceof ApiError?e.message:"Unable to load service orders")}finally{setLoading(false)}}
 useEffect(()=>{void load()},[]);
 async function update(id:string,status:string){setBusy(id);setError("");try{await api.patch(`/api/service-orders/vendor/${id}/status`,{status});await load()}catch(e){setError(e instanceof ApiError?e.message:"Unable to update order")}finally{setBusy("")}}
 return <div className="shell py-8"><div><p className="text-xs font-semibold uppercase tracking-[0.16em] text-ember-600">TTFL Services</p><h1 className="mt-1 text-2xl font-bold">Service orders</h1><p className="mt-1 text-sm text-graphite-500">Manage customer bookings and paid service requests.</p></div>{error&&<p className="mt-4 rounded-xl bg-red-50 p-3 text-sm font-medium text-red-700">{error}</p>}{loading?<div className="py-16 text-center text-sm text-graphite-500">Loading service orders…</div>:orders.length===0?<div className="mt-6 rounded-card border border-dashed border-graphite-300 p-12 text-center"><CalendarCheck className="mx-auto h-9 w-9 text-graphite-400"/><h2 className="mt-3 font-semibold">No service orders yet</h2><p className="mt-1 text-sm text-graphite-500">Paid service bookings will appear here.</p></div>:<div className="mt-6 space-y-4">{orders.map(o=><article key={o.id} className="rounded-card border border-graphite-200 bg-white p-5 dark:border-graphite-700 dark:bg-graphite-900"><div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div><h2 className="font-semibold">{o.serviceTitle}</h2><div className="mt-2 flex flex-wrap gap-x-4 gap-y-2 text-sm text-graphite-500"><span className="flex items-center gap-1.5"><UserRound className="h-4 w-4"/>{[o.customerFirstName,o.customerLastName].filter(Boolean).join(" ")||o.customerEmail}</span>{o.booking_date&&<span className="flex items-center gap-1.5"><CalendarCheck className="h-4 w-4"/>{o.booking_date}{o.booking_time?` · ${o.booking_time}`:""}</span>}{o.location&&<span className="flex items-center gap-1.5"><MapPin className="h-4 w-4"/>{o.location}</span>}</div></div><div className="text-left lg:text-right"><p className="text-lg font-bold">₦{Number(o.amount).toLocaleString()}</p><div className="mt-1 flex flex-wrap gap-2 lg:justify-end"><span className="rounded-full bg-cloud-100 px-2.5 py-1 text-xs font-semibold dark:bg-graphite-800">{label(o.payment_status)}</span><span className="rounded-full bg-ember-50 px-2.5 py-1 text-xs font-semibold text-ember-700">{label(o.status)}</span></div></div></div>{o.notes&&<div className="mt-4 rounded-xl bg-cloud-50 p-3 text-sm text-graphite-600 dark:bg-graphite-800 dark:text-graphite-300"><span className="font-semibold">Customer notes:</span> {o.notes}</div>} {nextActions[o.status]?.length>0&&<div className="mt-4 flex flex-wrap gap-2">{nextActions[o.status].map(status=><button key={status} type="button" disabled={busy===o.id} onClick={()=>void update(o.id,status)} className="inline-flex items-center gap-2 rounded-xl border border-graphite-200 px-3 py-2 text-xs font-semibold hover:border-ember-500 hover:text-ember-600 disabled:opacity-60 dark:border-graphite-700">{busy===o.id&&<Loader2 className="h-3.5 w-3.5 animate-spin"/>}{status==="CANCELLED"?"Cancel":`Mark ${label(status)}`}</button>)}</div>}</article>)}</div>}</div>;
}
